def match(orders):
    trades = []

    # Book structure: {side: [(price, arrival_time, order_id, remaining_qty), ...]}
    buy_book = []   # Sorted by (price desc, arrival_time asc)
    sell_book = []  # Sorted by (price asc, arrival_time asc)

    # Track order state: {order_id: (side, price, remaining_qty, arrival_time) or None if cancelled/filled}
    order_state = {}
    arrival_time = 0

    for order in orders:
        arrival_time += 1

        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_state and order_state[order_id] is not None:
                order_state[order_id] = None

        elif order[0] in ['limit', 'ioc', 'market']:
            order_type = order[0]
            order_id = order[1]
            side = order[2]
            qty = order[4] if order_type in ['limit', 'ioc'] else order[3]
            price = order[3] if order_type in ['limit', 'ioc'] else None

            remaining = qty

            if side == 'buy':
                # Match against sell book
                i = 0
                while i < len(sell_book) and remaining > 0:
                    sell_price, sell_time, sell_id, sell_qty = sell_book[i]

                    # Check if order_state still valid (not cancelled)
                    if order_state.get(sell_id) is None:
                        sell_book.pop(i)
                        continue

                    # Buy matches sells at or below its price (or any price for market)
                    if order_type == 'market' or price >= sell_price:
                        trade_qty = min(remaining, sell_qty)
                        trades.append([order_id, sell_id, sell_price, trade_qty])
                        remaining -= trade_qty
                        sell_qty -= trade_qty

                        if sell_qty == 0:
                            order_state[sell_id] = None
                            sell_book.pop(i)
                        else:
                            sell_book[i] = (sell_price, sell_time, sell_id, sell_qty)
                            order_state[sell_id] = (side, sell_price, sell_qty, sell_time)
                            i += 1
                    else:
                        break

                # Add to book if limit order and has remaining qty
                if remaining > 0 and order_type == 'limit':
                    buy_book.append((price, arrival_time, order_id, remaining))
                    buy_book.sort(key=lambda x: (-x[0], x[1]))  # Sort by price desc, then time asc
                    order_state[order_id] = ('buy', price, remaining, arrival_time)
                else:
                    if remaining == qty:  # Not matched at all
                        order_state[order_id] = None if order_type in ['ioc', 'market'] else None
                    else:
                        order_state[order_id] = None

            else:  # sell
                # Match against buy book
                i = 0
                while i < len(buy_book) and remaining > 0:
                    buy_price, buy_time, buy_id, buy_qty = buy_book[i]

                    # Check if order_state still valid (not cancelled)
                    if order_state.get(buy_id) is None:
                        buy_book.pop(i)
                        continue

                    # Sell matches buys at or above its price (or any price for market)
                    if order_type == 'market' or price <= buy_price:
                        trade_qty = min(remaining, buy_qty)
                        trades.append([buy_id, order_id, buy_price, trade_qty])
                        remaining -= trade_qty
                        buy_qty -= trade_qty

                        if buy_qty == 0:
                            order_state[buy_id] = None
                            buy_book.pop(i)
                        else:
                            buy_book[i] = (buy_price, buy_time, buy_id, buy_qty)
                            order_state[buy_id] = ('buy', buy_price, buy_qty, buy_time)
                            i += 1
                    else:
                        break

                # Add to book if limit order and has remaining qty
                if remaining > 0 and order_type == 'limit':
                    sell_book.append((price, arrival_time, order_id, remaining))
                    sell_book.sort(key=lambda x: (x[0], x[1]))  # Sort by price asc, then time asc
                    order_state[order_id] = ('sell', price, remaining, arrival_time)
                else:
                    if remaining == qty:  # Not matched at all
                        order_state[order_id] = None if order_type in ['ioc', 'market'] else None
                    else:
                        order_state[order_id] = None

    return trades

